import{_ as a}from"./chunks/layer-settings.Dcq49T8r.js";import{_ as t,o as s,c as o,a2 as r}from"./chunks/framework.Boholvbs.js";const n="/docs/assets/post-type-maps.DA7TIGjz.png",i="/docs/assets/map-sidebar.D1D6IpBM.png",p="/docs/assets/map-settings.zcLvXjy-.png",l="/docs/assets/map-layers.BTnpZtVD.png",d="/docs/assets/related-posts.DXAUn6Xr.png",w=JSON.parse('{"title":"Creating maps","description":"","frontmatter":{},"headers":[],"relativePath":"map-post.md","filePath":"map-post.md"}'),c={name:"map-post.md"};function g(h,e,m,y,u,f){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="creating-maps" tabindex="-1">Creating maps <a class="header-anchor" href="#creating-maps" aria-label="Permalink to &quot;Creating maps&quot;">​</a></h1><p>One of the custom post types that JEO plugin provides is <strong>Map</strong>.</p><p><img src="'+n+'" alt="Post Type Maps"></p><p>Entering the Map post editor, you&#39;ll see a preview of the current map (or a default map, if no layers are selected) and three sidebar panels: <strong>Map settings</strong>, <strong>Map layers</strong>, and <strong>Related posts</strong>.</p><p><img src="'+i+'" alt="Map Sidebar"></p><h2 id="map-settings" tabindex="-1">Map settings <a class="header-anchor" href="#map-settings" aria-label="Permalink to &quot;Map settings&quot;">​</a></h2><p>On the <strong>Map settings</strong> panel, you can change the initial center of the map by setting a latitude and longitude. You can also change the default zoom settings or even disable it.</p><p><img src="'+p+'" alt="Map settings"></p><p>When viewing a map in a post, clicking with the right mouse button and dragging makes the map rotate. Scrolling the mouse wheel changes the map zoom. Both of these options can be enabled or disabled with the checkboxes.</p><h2 id="map-layers" tabindex="-1">Map layers <a class="header-anchor" href="#map-layers" aria-label="Permalink to &quot;Map layers&quot;">​</a></h2><p>On the <strong>Map layers</strong> panel, you can visualize all the layers which are part of the map.</p><p><img src="'+l+'" alt="Map Layers"></p><p>Clicking on <strong>Edit layers settings</strong> opens a popup. There, you can add, remove and rearrange layers, define their types, and whether their legends will be shown on the map. You can also load specific interactions for each layer by clicking on <code>Load interactions</code>.</p><h3 id="legend-types" tabindex="-1">Legend types <a class="header-anchor" href="#legend-types" aria-label="Permalink to &quot;Legend types&quot;">​</a></h3><p>Each layer&#39;s legend can be set to one of these types:</p><ul><li><strong>Fixed</strong>: The layer is always visible. Good for base reference layers.</li><li><strong>Switchable</strong>: The user can toggle the layer on and off independently. Good for optional overlays.</li><li><strong>Swappable</strong>: Only one swappable layer is visible at a time (radio behavior). Good for comparing different datasets.</li></ul><h3 id="layer-styling" tabindex="-1">Layer styling <a class="header-anchor" href="#layer-styling" aria-label="Permalink to &quot;Layer styling&quot;">​</a></h3><p>Some layer types support custom styling. When using <strong>Mapbox vector tiles</strong> with <code>fill</code>, <code>line</code>, or <code>circle</code> geometry, a style editor allows you to customize colors, opacity, and filters. Layers generated by AI also come with a suggested default style that you can accept or override. Other layer types (Mapbox styles, tilesets, TileLayers) use the styling defined in their source.</p><p><img src="'+a+'" alt="Layer settings"></p><p><a href="./layer-post">Check out how to create new layers here</a></p><h2 id="related-posts" tabindex="-1">Related posts <a class="header-anchor" href="#related-posts" aria-label="Permalink to &quot;Related posts&quot;">​</a></h2><p>On the <strong>Related posts</strong> panel, you can set which geolocated posts will be used as markers on the map. You can filter posts by categories, tags, date interval, or — for advanced uses — meta queries using WordPress <code>post_meta</code>.</p><p><img src="'+d+'" alt="Related posts"></p>',23)])])}const v=t(c,[["render",g]]);export{w as __pageData,v as default};
